import{_ as n,o as i,c as h,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-6-view-user/report3_spec.md","filePath":"feature/admin-management/3-10-6-view-user/report3_spec.md"}'),g={name:"feature/admin-management/3-10-6-view-user/report3_spec.md"};function l(s,t,o,a,e,c){return i(),h("div",null,[...t[0]||(t[0]=[r("<p><strong>3.10.6 View User (Xem Danh Sách Người Dùng)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) truy cập danh sách người dùng tại route /admin/users.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên hệ thống tra cứu danh mục người dùng.</li><li><strong>Purpose</strong>: Tra cứu/lọc user theo trạng thái tài khoản, system role, gói catalog và strike còn hiệu lực; quyền Agency hiển thị riêng.</li><li><strong>Interface</strong>: Màn hình Danh sách Người dùng (SCR-ADM-06), gồm thanh tìm kiếm, các bộ lọc trạng thái/gói cước/thẻ phạt, bảng dữ liệu đa cột và thanh phân trang.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN, truy vấn hồ sơ phân trang với trạng thái hiện tại, cờ kích hoạt và catalog subscription; tính bộ đếm theo FR 3.10.5 thay vì TTL từ ngày tạo.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Màn hình Danh sách &amp; Quản lý Người dùng (SCR-ADM-06):</p><ul><li>Left/Header: Sidebar điều hướng Admin; Top Header hiển thị breadcrumb &quot;Admin / Quản lý Người dùng&quot; và chỉ báo tổng số người dùng.</li><li>Center: Tìm email/tên; lọc ACTIVE, PENDING_VERIFICATION, FLAGGED, DEACTIVATED, DELETED và SUSPENDED cũ nếu còn; ADMIN/USER; gói catalog; mức strike còn hiệu lực. Dòng hiển thị hồ sơ, system role, quyền sở hữu Agency riêng, gói hiện tại/chờ, bộ đếm YELLOW/ORANGE/RED, trạng thái kích hoạt và hạn khóa. Ngưỡng ORANGE là x/3.</li><li>Buttons: Nút &quot;+ Tạo người dùng mới&quot; (màu xanh góc phải trên), Nút &quot;Áp dụng lọc&quot;, Nút &quot;Đặt lại&quot;, Menu thao tác ba chấm trên từng dòng (Xem chi tiết, Quản lý vi phạm, Chỉnh sửa).</li><li>Footer: Phân trang: 10/20/50 dòng mỗi trang, điều hướng trang và tổng số; mặc định 20 dòng.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Không có (mặc định page=1, limit=20).</li><li><strong>Input optional</strong>: page, limit, search, status, systemRole (ADMIN/USER), strikeFilter (ALL/HAS_YELLOW/HAS_ORANGE/HAS_RED/CLEAN), planId (catalog), sortBy, sortOrder.</li><li><strong>System data</strong>: Danh sách bản ghi users kèm thông tin gói cước và bộ đếm thẻ phạt activeStrikes30d.</li><li><strong>Output</strong>: Danh sách người dùng kèm siêu dữ liệu phân trang (total, page, limit, totalPages).</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Chỉ ADMIN xem danh bạ toàn nền tảng.</li><li><strong>BR-82</strong>: System role chỉ gồm ADMIN và USER. Quyền thành viên Agency/Workspace quản lý riêng. Mã gói lấy từ catalog subscription hiện có (hiện tại BASIC, PRO, ENTERPRISE), không tạo danh mục gói cứng khác.</li><li><strong>BR-94</strong>: Dùng trạng thái thẻ còn hiệu lực/đã quy đổi/đã gỡ/hết hạn tại FR 3.10.5. Không nhầm bộ đếm hiệu lực với lịch sử; ORANGE hiển thị x/3.</li><li><strong>BR-15</strong>: PENDING_VERIFICATION là chưa xác thực email. DEACTIVATED hiển thị hạn khóa. DELETED là vòng đời tự xóa riêng.</li><li><strong>BR-65</strong>: Giữ phân trang, tìm kiếm và bộ lọc trên URL; kiểm tra tham số và allowlist sắp xếp. Không trả hash mật khẩu, token hoặc bí mật Authenticator.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu quyền ADMIN → MSG39.</li><li>Không tìm thấy user phù hợp → bảng trống kèm MSG122.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin truy cập màn hình Danh sách Người dùng tại /admin/users.</li><li>Hệ thống xác thực quyền ADMIN theo BR-35, BR-63.</li><li>Hệ thống tải dữ liệu trang 1 (20 bản ghi mới nhất) và hiển thị lên bảng SCR-ADM-06.</li><li>Admin có thể nhập từ khóa tìm kiếm (họ tên, email) hoặc chọn lọc theo Trạng thái / Thẻ phạt / Gói cước.</li><li>Hệ thống gửi yêu cầu lọc về backend và tải lại danh sách kết quả phù hợp.</li><li>Admin có thể chuyển trang hoặc thay đổi số lượng bản ghi hiển thị trên mỗi trang.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Thiếu quyền ADMIN → MSG39.</li><li>5.a1: Không có user phù hợp → trạng thái trống với MSG122; giữ bộ lọc hiện tại.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Danh bạ phân trang phản ánh nhất quán kích hoạt/xử phạt, gói catalog và vòng đời strike.</li><li>Tham số tìm kiếm và lọc được giữ trên URL.</li></ul>",14)])])}const m=n(g,[["render",l]]);export{p as __pageData,m as default};
